from pathlib import Path
import json,runpy,datetime,hashlib
own=Path(__file__).parent
ids=json.loads((own/'selected-ten-current-goal-ids.author.json').read_text())
inputs=json.loads((own/'current-ten-whole-DEEN-goals.actual.json').read_text())
goals=inputs['wholeGoals']
cases=runpy.run_path(str(own/'author-case-library.part1.actual.py'))['CASES']+runpy.run_path(str(own/'author-case-library.part2.actual.py'))['CASES']
assert len(cases)==20 and len({x['id'] for x in cases})==20
for case in cases:
    case['goalId']=ids[case['ordinal']-1]
    for field in ['material','task','modelAnswer']:
        assert all(case[field][lang].strip() for lang in ['de','en'])
ESS=[
('Biologie untersucht Leben: Lebewesen, Lebensvorgänge und Beziehungen; begründete Aussagen benötigen geeignete nachvollziehbare Belege.', 'Biology studies life: organisms, life processes and relationships; justified statements require suitable traceable evidence.', 'Der Gegenstandsbereich umfasst Pflanzen, Tiere, Pilze und Belege früheren Lebens; Fragen und persönliche Wertungen sind noch keine geprüften Ergebnisse.', 'Its scope includes plants, animals, fungi and evidence of past life; questions and personal judgments are not yet tested findings.'),
('Grundlegende Lebenskennzeichen werden nach Organisation, Stoffwechsel, Entwicklung und Reaktion geordnet und gemeinsam beurteilt.', 'Fundamental characteristics of life are organized by organization, metabolism, development and response and assessed together.', 'Momentan fehlende sichtbare Bewegung oder individuelle Fortpflanzung schließt Leben nicht allein aus; Einzelfeatures werden im System und Lebensverlauf bewertet.', 'Lack of visible movement at a moment or individual reproduction alone does not exclude life; individual features are evaluated in the system and life history.'),
('Sachgerechte Präparation und Mikroskopbedienung bilden einen geordneten praktischen Ablauf mit dünner Probe, geeigneter Montage, Beleuchtung und sicherer Fokussierung.', 'Correct specimen preparation and microscope operation form an organized practical workflow involving a thin sample, appropriate mounting, illumination and safe focusing.', 'Fehlersuche unterscheidet Artefakte und Schärfeebenen von Zellmerkmalen; beschriebene Planung ersetzt keine tatsächlich beobachtete praktische Bedienung.', 'Troubleshooting distinguishes artifacts and focal levels from cell characteristics; described planning does not replace actual observed operation.'),
('Bestandteile einer dargestellten Pflanzenzelle werden benannt und funktional verknüpft, insbesondere unterschiedliche Wand- und Membranfunktionen.', 'Components of a represented plant cell are named and related functionally, especially the different functions of wall and membrane.', 'Ein räumliches grünes Blattzellmodell erklärt Funktionen, ohne jedes Pflanzengewebe gleichzusetzen oder alle Bestandteile in jeder Aufnahme als sichtbar auszugeben.', 'A spatial green leaf-cell model explains functions without equating all plant tissues or claiming that every component is visible in every image.'),
('Der Vergleich bekannter Pflanzen- und Tierzellen ordnet gemeinsame Strukturen und kontextabhängige Unterschiede statt isolierter Modellformen.', 'Comparison of known plant and animal cells organizes shared structures and context-dependent differences rather than isolated model outlines.', 'Nicht grüne Pflanzenzellen bleiben Pflanzenzellen; fehlende Chloroplasten oder eine geometrische Form allein liefern keine universelle Zellzuordnung.', 'Nongreen plant cells remain plant cells; absent chloroplasts or geometric shape alone do not universally identify a cell type.'),
('Der experimentelle Lichtvergleich variiert Licht gezielt, kontrolliert andere Einflussgrößen und deutet geeignete Produkt- oder Aktivitätsbefunde mit Fehlergrenzen.', 'An experimental light comparison deliberately varies light, controls other factors and interprets appropriate product or activity findings with error limits.', 'Ein kontrollierter Nettobefund ist von bloßer Bläschenzählung, Erwärmung und unbegrenzter linearer Steigerung zu unterscheiden; praktische Durchführung bleibt eigene Evidenz.', 'A controlled net finding must be distinguished from bubble counts alone, heating and unlimited linear increase; actual execution remains its own evidence.'),
('CO2- und ausreichendes Wasserangebot werden in getrennten kontrollierten Vergleichen als Bedingungen pflanzlicher Fotosyntheseleistung untersucht.', 'CO2 and adequate water availability are investigated through separate controlled comparisons as conditions of plant photosynthetic performance.', 'Wasserstress verändert auch Gaszugang und Physiologie; ein Bedarfs-/Abhängigkeitsversuch beweist nicht unmittelbar die chemische Substratrolle von Wasser.', 'Water stress also affects gas access and physiology; a requirement or dependence experiment does not directly establish water’s chemical substrate role.'),
('Stärke und Sauerstoff werden durch jeweils passende Nachweisverfahren mit Referenzen, Kontrollen und dokumentierter Durchführung identifiziert.', 'Starch and oxygen are identified by their respective appropriate assays with references, controls and documented execution.', 'Bläschen allein bestimmen kein Gas, Iod bestimmt nicht beliebigen Zucker, und ein Netto-Sauerstoffbefund oder positiver Gasnachweis beweist keine Reinheit oder Bruttorate.', 'Bubbles alone do not identify gas, iodine does not identify arbitrary sugar, and a net oxygen result or positive gas test establishes neither purity nor a gross rate.'),
('Die zusammenfassende Wortgleichung verbindet CO2 und Wasser mit aufgebautem Zucker und abgegebenem Sauerstoff unter Nutzung von Lichtenergie.', 'The summary word equation relates CO2 and water to sugar formation and oxygen release using light energy.', 'Stoffliche Inputs, Energiezufuhr, Mineralversorgung und nachfolgende Speicherung als Stärke werden unterschieden; das Gesamtmodell zeigt nicht alle Zwischenreaktionen.', 'Material inputs, energy supply, mineral nutrition and subsequent starch storage are distinguished; the overall model does not show all intermediate reactions.'),
('Fotosynthese baut energiereiche organische Stoffe auf und liefert Sauerstoff; Zellatmung nutzt solche Stoffe für nutzbare Energie und bildet CO2 und Wasser.', 'Photosynthesis builds energy-rich organic substances and supplies oxygen; cellular respiration uses such substances for usable energy and produces CO2 and water.', 'Pflanzen atmen unter den gegebenen Bedingungen im Licht und Dunkeln; Nettobilanzen und Reservewachstum werden erklärt, ohne die Bedeutung der Fotosynthese für Wachstum, Nahrung und Sauerstoff aufzugeben.', 'Plants respire in light and darkness under the stated conditions; net balances and growth from reserves are explained without discarding the importance of photosynthesis for growth, food and oxygen.')]
VAR=[
('Fragenkarten zu Entwicklung und Beziehungen versus Pflanzen/Pilze/Fossilien.', 'Question cards about development and relationships versus plants, fungi and fossils.'),
('Lebensmerkmalsgruppen gegenüber Kristall/Roboter versus ruhender Samen und steriles Tier.', 'Groups of life characteristics versus crystal and robot, then a dormant seed and sterile animal.'),
('Erstpräparation und Bedienreihenfolge versus Fehlersuche bei Falten, Luftblasen und Schärfeebenen.', 'Initial preparation and operating sequence versus troubleshooting folds, bubbles and focal levels.'),
('Räumliches grünes Blattzellmodell versus nicht grüne Zelle und getrennte Wand-/Membranschädigung.', 'Spatial green leaf-cell model versus a nongreen cell and separate wall and membrane damage.'),
('Grüne Blattzelle/Mundschleimhaut versus bekannte Wurzel-/Tier-Epithelproben mit Zuordnungsgrenze.', 'Green leaf cell and cheek epithelium versus known root and animal epithelial samples with identification limits.'),
('Kontrollierter Blatt-Stärketest versus kalibrierte Lichtreihe mit Nettosignal und ungeeigneter Bläschenreihe.', 'Controlled leaf starch assay versus a calibrated illumination series with a net signal and unsuitable bubble series.'),
('Getrennte CO2-/Wasserreihen mit Wiederwässerung versus Korrektur eines mehrfach veränderten Versuchs.', 'Separate CO2 and water series with rewatering versus correction of a multi-factor comparison.'),
('Stärketest und betreute Gasprobe versus Glucosekontrolle und kalibrierter Sauerstoffsensor.', 'Starch assay and supervised gas test versus a glucose control and calibrated oxygen sensor.'),
('Gleichungskarten versus organischer Aufbau ohne Erde und Speicherung als Stärke.', 'Equation cards versus organic synthesis without soil and storage as starch.'),
('Netto-CO2-Bilanz Licht/Dunkel versus Dunkelwachstum aus Knollenreserven und längerfristige Ernährung.', 'Net CO2 balance in light and darkness versus dark growth from tuber reserves and longer-term nutrition.')]
profiles=[]
for i,goal in enumerate(goals):
    ordinal=i+1;pair=[x for x in cases if x['ordinal']==ordinal];assert len(pair)==2
    corede,coreen,transferde,transferen=ESS[i]
    coreid=f'he7-ten-{ordinal:02d}-core';transferid=f'he7-ten-{ordinal:02d}-transfer'
    profile={'archetype':'procedure' if ordinal==3 else 'experiment' if ordinal in [6,7,8] else 'representation' if ordinal==9 else 'concept',
      'expectations':[{'id':coreid,'essentialUnderstandingDe':corede,'essentialUnderstandingEn':coreen,'observablePerformanceDe':pair[0]['task']['de'],'observablePerformanceEn':pair[0]['task']['en']},{'id':transferid,'essentialUnderstandingDe':transferde,'essentialUnderstandingEn':transferen,'observablePerformanceDe':pair[1]['task']['de'],'observablePerformanceEn':pair[1]['task']['en']}],
      'coverageExpectations':{'requiredExpectationIds':[coreid,transferid],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},
      'variationAxes':[{'id':f'he7-ten-{ordinal:02d}-context-method','textDe':VAR[i][0],'textEn':VAR[i][1]}],
      'applicationCaseBriefs':[{'id':x['id'],'taskDemandDe':x['material']['de']+' '+x['task']['de'],'taskDemandEn':x['material']['en']+' '+x['task']['en'],'expectedPerformanceDe':x['modelAnswer']['de'],'expectedPerformanceEn':x['modelAnswer']['en'],'understandingFocusDe':corede+' '+transferde,'understandingFocusEn':coreen+' '+transferen} for x in pair]}
    profiles.append({'goalId':goal['id'],'reason':'New own whole bilingual public-model cases for this unchanged entire goal; actual independent whole science/source/performance review and later raster/native D/V still pending. No old current A/M record changed or science approval inferred from technical reuse.','evidenceLevel':'E1','maximumClaimScope':'G1','dissent':['Author of these cases, not their independent reviewer; ai_candidate/needs_human_review, no actual experiments or pupil evidence.','Whole original HE5.1/7.1/7.2 source scope and optional/method-recommendation limits retained. No new per-country route approval from unchanged raw16-country applicability.','No task quota after sufficient evidence. Independent demonstrations can be aspects/transfer within one genuine task; supplied two cases are available variations, not compulsory extra tasks.','For practical/experimental goals, interpreting this synthetic material or reciting a plan alone does not establish real execution skill. Actual appropriate practical actions and traceable records are required when claiming that competence.','Photosynthesis cases preserve gas-identity/net-gross/physiological-water inference limits. No direct chemical water-substrate proof from drought or stomatal closure.'],'profile':profile})
